using System.Globalization;
using System.Net;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using CleanHome.Payment.Api.Configuration;
using CleanHome.Payment.Api.Models;
using CleanHome.ServiceDefaults;
namespace CleanHome.Payment.Api.Services;
public sealed class VnPayGateway(VnPayOptions options,IHttpClientFactory clients){
 public static string Canonical(IEnumerable<KeyValuePair<string,string>> values)=>string.Join("&",values.Where(p=>!string.IsNullOrEmpty(p.Value)&&p.Key is not ("vnp_SecureHash" or "vnp_SecureHashType")).OrderBy(p=>p.Key,StringComparer.Ordinal).Select(p=>WebUtility.UrlEncode(p.Key)+"="+WebUtility.UrlEncode(p.Value)));
 public static string Sign(string secret,string text)=>Convert.ToHexString(HMACSHA512.HashData(Encoding.UTF8.GetBytes(secret),Encoding.UTF8.GetBytes(text))).ToLowerInvariant();
 public static bool Matches(string expected,string actual){try{return CryptographicOperations.FixedTimeEquals(Convert.FromHexString(expected),Convert.FromHexString(actual));}catch(FormatException){return false;}}
 public string Create(string reference,decimal amount,string created,DateTime expires,string ip){options.Require();var values=new Dictionary<string,string>{["vnp_Version"]="2.1.0",["vnp_Command"]="pay",["vnp_TmnCode"]=options.Get("TMN_CODE"),["vnp_Amount"]=(amount*100).ToString("0",CultureInfo.InvariantCulture),["vnp_CurrCode"]="VND",["vnp_TxnRef"]=reference,["vnp_OrderInfo"]="Thanh toan CleanHome "+reference,["vnp_OrderType"]="other",["vnp_Locale"]="vn",["vnp_ReturnUrl"]=options.Get("RETURN_URL"),["vnp_CreateDate"]=created,["vnp_ExpireDate"]=expires.AddHours(7).ToString("yyyyMMddHHmmss",CultureInfo.InvariantCulture),["vnp_IpAddr"]=ip};var text=Canonical(values);return options.Get("PAYMENT_URL")+"?"+text+"&vnp_SecureHash="+Sign(options.Get("HASH_SECRET"),text);}
 public ProviderResult? Verify(IQueryCollection query){options.Require();if(query.Any(p=>p.Value.Count!=1)||query.Count>30)return null;var fields=query.Where(p=>p.Key.StartsWith("vnp_",StringComparison.Ordinal)).ToDictionary(p=>p.Key,p=>p.Value.ToString(),StringComparer.Ordinal);if(!fields.TryGetValue("vnp_SecureHash",out var hash)||!Matches(Sign(options.Get("HASH_SECRET"),Canonical(fields)),hash)||fields.GetValueOrDefault("vnp_TmnCode")!=options.Get("TMN_CODE"))return null;if(!decimal.TryParse(fields.GetValueOrDefault("vnp_Amount"),NumberStyles.None,CultureInfo.InvariantCulture,out var amount)||amount<=0)return null;return new(fields.GetValueOrDefault("vnp_TxnRef")??"",amount/100,fields.GetValueOrDefault("vnp_ResponseCode")??"",fields.GetValueOrDefault("vnp_TransactionStatus")??"",fields.GetValueOrDefault("vnp_TransactionNo")??"",fields.GetValueOrDefault("vnp_PayDate")??"",Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(Canonical(fields)))));}
 public async Task<ProviderResult?> Query(PaymentAttempt attempt,CancellationToken ct){options.Require();var id=Guid.NewGuid().ToString("N");var now=DateTime.UtcNow.AddHours(7).ToString("yyyyMMddHHmmss",CultureInfo.InvariantCulture);var values=new Dictionary<string,string>{["vnp_RequestId"]=id,["vnp_Version"]="2.1.0",["vnp_Command"]="querydr",["vnp_TmnCode"]=options.Get("TMN_CODE"),["vnp_TxnRef"]=attempt.Reference,["vnp_TransactionDate"]=attempt.CreateDate,["vnp_CreateDate"]=now,["vnp_IpAddr"]="127.0.0.1",["vnp_OrderInfo"]="Doi soat CleanHome"};values["vnp_SecureHash"]=Sign(options.Get("HASH_SECRET"),string.Join('|',new[]{id,"2.1.0","querydr",values["vnp_TmnCode"],attempt.Reference,attempt.CreateDate,now,"127.0.0.1",values["vnp_OrderInfo"]}));using var response=await clients.CreateClient("vnpay").PostAsJsonAsync("https://sandbox.vnpayment.vn/merchant_webapi/api/transaction",values,ct);if(!response.IsSuccessStatusCode)throw new ApiException(503,"VNPay chưa trả kết quả đối soát.");var json=await response.Content.ReadFromJsonAsync<Dictionary<string,string>>(ct)??[];string V(string key)=>json.GetValueOrDefault(key)??"";
  var signed=string.Join('|',new[]{"vnp_ResponseId","vnp_Command","vnp_ResponseCode","vnp_Message","vnp_TmnCode","vnp_TxnRef","vnp_Amount","vnp_BankCode","vnp_PayDate","vnp_TransactionNo","vnp_TransactionType","vnp_TransactionStatus","vnp_OrderInfo"}.Select(V));if(!Matches(Sign(options.Get("HASH_SECRET"),signed),V("vnp_SecureHash"))||V("vnp_TmnCode")!=options.Get("TMN_CODE")||V("vnp_TxnRef")!=attempt.Reference)throw new ApiException(502,"Kết quả đối soát không hợp lệ.");if(V("vnp_ResponseCode")!="00"||V("vnp_TransactionStatus") is "01" or "05" or "06")return null;
  if(!decimal.TryParse(V("vnp_Amount"),NumberStyles.None,CultureInfo.InvariantCulture,out var amount))throw new ApiException(502,"Số tiền đối soát không hợp lệ.");return new(attempt.Reference,amount/100,V("vnp_TransactionStatus")=="00"?"00":"99",V("vnp_TransactionStatus"),V("vnp_TransactionNo"),V("vnp_PayDate"),Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(signed))));
 }
}
